import { basename, isAbsolute, join, normalize } from 'pathe';
import type {
	BrowserConsoleMessage,
	BrowserLaunchOptions,
	BrowserNetworkConditions,
	BrowserNetworkRequest,
	BrowserPageError,
	BrowserRequestFailure,
	WitnessBrowser,
	WitnessBrowserPage,
	WitnessBrowserSession,
} from '@async/witness';
import {
	chromium,
	type Browser,
	type BrowserContext,
	type BrowserContextOptions,
	type CDPSession,
	type Download,
	type Page,
	type Request,
	type Route,
} from 'playwright';
import { parseHost, parseURL } from 'ufo';
import { sha256 } from '../../../core/src/receipts/canonicalize.ts';

export type ServiceWorkerTelemetry = {
	state: 'ready' | 'timeout';
	registration: {
		scriptPath: string | null;
		scope: string | null;
		installing: string | null;
		waiting: string | null;
		active: string | null;
	};
	controller: string | null;
	cacheNames: string[];
	cacheEntries: Array<{ name: string; paths: string[] }>;
	workerEvents: Array<
		| { kind: 'registration'; scopePath: string }
		| { kind: 'version'; scriptPath: string; status: string; runningStatus: string }
		| {
				kind: 'error';
				message: string;
				sourcePath: string;
				lineNumber: number;
				columnNumber: number;
		  }
	>;
};

export type WitnessTransportRequest = {
	protocol: string;
	host: string;
	pathname: string;
	search: string;
	method: string;
	resourceType: string;
};

